using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
static class V111Checks {
 public static void Startup(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"startup-state-"+Guid.NewGuid().ToString("N"));var log=new List<string>();var main=new MainWindow();var watch=new System.Diagnostics.Stopwatch();main.ContentRendered+=(s,e)=>watch.Start();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(25)};bool checking=false;timer.Tick+=async(s,e)=>{if(checking)return;var welcome=app.Windows.OfType<WelcomeWindow>().FirstOrDefault();if(welcome==null)return;checking=true;timer.Stop();try{bool staged=Transitions.IsComplete(main)&&watch.ElapsedMilliseconds>=700;log.Add((staged?"PASS ":"FAIL ")+"Welcome waits for the main opening fade ("+watch.ElapsedMilliseconds+" ms)");bool ready=await Transitions.WhenReady(welcome);bool faded=ready&&Transitions.IsComplete(welcome)&&Transitions.Duration(welcome)==500;log.Add((faded?"PASS ":"FAIL ")+"Real startup welcome completes 500 ms fade");Theme.Capture((FrameworkElement)welcome.Content,Path.Combine(Path.GetDirectoryName(path),"启动欢迎弹窗.png"),144);log.Add(staged&&faded?"ALL STARTUP CHECKS PASSED":"STARTUP FAILED");File.WriteAllLines(path,log.ToArray());welcome.Close();main.Close();if(!staged||!faded)Environment.ExitCode=1;}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray());app.Shutdown(1);}};timer.Start();app.Run(main);}
 static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 public static void Run(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"patch-state-"+Guid.NewGuid().ToString("N"));var log=new List<string>();Action<bool,string> check=(ok,s)=>{log.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(path,log.ToArray());if(!ok)throw new Exception(s);};int failuresOpened=0;EventManager.RegisterClassHandler(typeof(FailureWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler((s,e)=>failuresOpened++));var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{
   check(Transitions.Duration(main)==800&&!Transitions.IsComplete(main),"Main window begins its 800 ms opening transition");await Transitions.WhenReady(main);check(Transitions.IsComplete(main)&&Math.Abs(((FrameworkElement)main.Content).Opacity-1)<.001,"Main window finishes fully opaque");main.PreviewSize(1600,1000);
   var lessons=PracticeKnowledge.All;check(lessons.Count==90&&lessons.Select(x=>x.Problem.Id).SequenceEqual(Enumerable.Range(1,90)),"90 ordinary practice lessons follow question order");check(lessons.All(l=>l.Goal.Length>15),"All 90 questions have a specific learning goal");var fresh=lessons.SelectMany(l=>l.New).ToList();check(fresh.Count>=30&&fresh.Select(t=>t.Key).Distinct().Count()==fresh.Count,"New syntax is introduced once, with more than 30 topics");foreach(var l in lessons){check(l.New.All(t=>t.FirstProblem==l.Problem.Id)&&l.Review.All(t=>t.FirstProblem<l.Problem.Id),"New/review syntax chronology for question "+l.Problem.Id);}check(PracticeKnowledge.For(1).New.Any(t=>t.Key=="scanf")&&PracticeKnowledge.For(61).New.Any(t=>t.Key=="pointer")&&PracticeKnowledge.For(63).New.Any(t=>t.Key=="recursion")&&PracticeKnowledge.For(81).New.Any(t=>t.Key=="memory"),"Core IO, pointers, recursion and dynamic allocation have lessons");
   var knowledge=new KnowledgeWindow(Bank.All()[60]){Owner=main};knowledge.Show();check(Transitions.Duration(knowledge)==500&&!Transitions.IsComplete(knowledge),"Knowledge popup starts a 500 ms transition");await Transitions.WhenReady(knowledge);check(Transitions.IsComplete(knowledge)&&knowledge.Lesson.Problem.Id==61,"Knowledge popup becomes readable and targets current question");Theme.Capture((FrameworkElement)knowledge.Content,Path.Combine(Path.GetDirectoryName(path),"普通练习知识点.png"),144);knowledge.Close();
   foreach(Window dialog in new Window[]{new WelcomeWindow(),new AnswerWindow(Bank.All()[0]),new ResultsWindow(new Evaluation{Code="",Title="test",Time="test"},Bank.All()[0]),new AppDialog("这是带淡入效果的说明与确认窗口。","提示",MessageBoxButton.YesNo)}){dialog.Owner=main;dialog.Show();check(Transitions.Duration(dialog)==500,"500 ms transition for "+dialog.GetType().Name);await Transitions.WhenReady(dialog);check(Transitions.IsComplete(dialog),"Dialog completes: "+dialog.GetType().Name);dialog.Close();}
   var early=new AppDialog("早关闭检查","提示"){Owner=main};((Window)early).Show();early.Close();check(!await Transitions.WhenReady(early),"Closing during fade does not leave a pending task");
   var editor=Field<CodeEditor>(main,"editor");editor.Text="int main(void){return ???;}";await main.Evaluate(false);check(failuresOpened==0&&Field<Border>(main,"warningBanner").Visibility==Visibility.Visible&&Field<TextBlock>(main,"warningText").Text.Contains("0 / 100")&&Field<TextBox>(main,"outputDetail").Text.Contains("中文解释"),"Ordinary compile error gives inline score warning and Chinese diagnostics, no execution animation");
   editor.Text="#include <stdio.h>\nint main(void){puts(\"WRONG\");return 0;}";await main.Evaluate(false);check(failuresOpened==0&&Field<TextBlock>(main,"warningText").Text.Contains("尚未达到60分"),"Ordinary score below 60 warns without a modal window");
   foreach(double dpi in new[]{96.0,144.0,192.0}){main.PreviewSize(2560*96/dpi,1600*96/dpi);await Task.Delay(90);check(editor.Input.ActualHeight>200&&editor.Input.ActualWidth>550,"Warning/knowledge controls keep editor usable at "+dpi+" DPI");Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"普通警告-"+dpi+"dpi.png"),dpi);}main.PreviewSize(1600,1000);
   editor.Text="int main(void){return 7;}";await main.Evaluate(false);check(failuresOpened==0&&Field<TextBlock>(main,"warningText").Text.Contains("运行失败"),"Ordinary abnormal exit warns without execution animation");
   editor.Text=Bank.All()[0].Reference;await main.Evaluate(false);check(Field<Border>(main,"warningBanner").Visibility==Visibility.Collapsed&&Field<Evaluation>(main,"evaluation").Score==100&&editor.Input.IsReadOnly==false,"Successful retry clears warning and leaves editing enabled");await Task.Delay(1100);
   var ev=new Evaluation{Compiled=true,Score=59.9};check(PracticeFeedback.Warning(ev)!="","59.9 warns");ev.Score=60;check(PracticeFeedback.Warning(ev)=="","60 is not a low-score warning");
   var game=new ChallengeWindow(true){Owner=main};game.Show();await Transitions.WhenReady(game);check(Transitions.Duration(game)==500&&ChallengeBank.Levels.First().Seconds==180&&ChallengeBank.Levels.Last().Seconds==600,"Challenge entrance fades, preserves 3-10 minute limits");game.StartForCheck();game.Editor.Text="int main(void){return ???;}";int previous=failuresOpened;await game.Judge();check(failuresOpened>previous&&!game.Progress.Passed(1),"Challenge compile error still opens execution animation and does not unlock");game.Close();
   Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"主界面-2.5K.png"),153.6);log.Add("ALL VER1.1.1 CHECKS PASSED");File.WriteAllLines(path,log.ToArray());main.Close();
  }catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray());app.Shutdown(1);}};app.Run(main);}
}
